blocks.value:
provider "aws" { region = var.aws_region }
module "aws_node" {
  source = "./modules/web_node"
  cloud  = "aws"
  region = "eu-west-1"
  name   = "sa-academy-aws"
}

provider "google" { project = var.gcp_project region = "europe-west1" }
module "gcp_node" {
  source = "./modules/web_node"
  cloud  = "gcp"
  region = "europe-west1"
  name   = "sa-academy-gcp"
}
